package am.zzws.admin;
import android.content.Context;import android.content.SharedPreferences;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.Base64;
import java.nio.charset.StandardCharsets;import java.security.KeyStore;import javax.crypto.Cipher;import javax.crypto.KeyGenerator;import javax.crypto.SecretKey;import javax.crypto.spec.GCMParameterSpec;import org.json.JSONObject;
/** Persist an uncertain submission before sending; bound to endpoint and account, never auto-resubmitted. */
final class SecurePendingOrder {
 private static final String ALIAS="zzws_pending_order_v1";
 private static SharedPreferences preferences(Context c){return c.getSharedPreferences("zzws_pending_orders",Context.MODE_PRIVATE);}
 private static SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(!s.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());g.generateKey();}return (SecretKey)s.getKey(ALIAS,null);}
 static void save(Context c,String user,JSONObject order)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD((EndpointConfiguration.API+"|"+user).getBytes(StandardCharsets.UTF_8));String v=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(order.toString().getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!preferences(c).edit().putString(user,v).commit())throw new Exception("Չհաջողվեց պահպանել ուղարկման նույնացուցիչը։ Պատվերը չի ուղարկվել։");}
 static JSONObject read(Context c,String user)throws Exception{String v=preferences(c).getString(user,"");if(v.isEmpty())return null;try{String[] p=v.split(":",-1);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],Base64.NO_WRAP)));cipher.updateAAD((EndpointConfiguration.API+"|"+user).getBytes(StandardCharsets.UTF_8));return new JSONObject(new String(cipher.doFinal(Base64.decode(p[1],Base64.NO_WRAP)),StandardCharsets.UTF_8));}catch(Exception e){throw new Exception("Նախորդ ուղարկման տեղական տվյալները չեն բացվում։ Նախ ստուգեք պատվերների պատմությունը։");}}
 static void clear(Context c,String user){preferences(c).edit().remove(user).commit();}
}
